package org.transittr;
import android.content.Context;import java.io.*;import java.util.*;import org.json.*;
public final class MetroData {
 private static ArrayList<JourneyData.RailLine> all;
 public static synchronized ArrayList<JourneyData.RailLine> lines(Context context,int city)throws IOException{if(all==null){try{InputStream in=context.getAssets().open("rail-networks.json");ByteArrayOutputStream out=new ByteArrayOutputStream();try{byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>524288)throw new IOException("Metro veri sınırı");out.write(b,0,n);}}finally{in.close();}JSONArray a=new JSONObject(new String(out.toByteArray(),"UTF-8")).getJSONArray("lines");ArrayList<JourneyData.RailLine> loaded=new ArrayList<JourneyData.RailLine>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);JourneyData.RailLine l=new JourneyData.RailLine();l.city=r.getInt("city");l.id=r.getString("id");l.name=r.getString("name");l.color=r.getString("color");JSONArray stops=r.getJSONArray("stations");for(int k=0;k<stops.length();k++){JSONObject s=stops.getJSONObject(k);double lat=s.getDouble("lat"),lon=s.getDouble("lon");if(lat<35||lat>43||lon<25||lon>45)throw new IOException("Geçersiz metro koordinatı");l.stations.add(new JourneyData.Station(s.getString("name"),lat,lon));}loaded.add(l);}all=loaded;}catch(JSONException e){throw new IOException("Metro verisi okunamadı");}}ArrayList<JourneyData.RailLine> result=new ArrayList<JourneyData.RailLine>();for(JourneyData.RailLine l:all)if(l.city==city)result.add(l);return result;}
 public static int countStations(ArrayList<JourneyData.RailLine> lines){HashSet<String> s=new HashSet<String>();for(JourneyData.RailLine l:lines)for(JourneyData.Station p:l.stations)s.add(p.name+":"+p.lat+":"+p.lon);return s.size();}
}
